const TreeBranch = ({ node, x, y, spacing, depth, colorClass }) =&gt; {
  if (!node || !node.children || node.children.length === 0) return null;

  const totalWidth = (node.children.length - 1) * spacing;

  return (
    &lt;g&gt;
      {node.children.map((child, i) =&gt; {
        const childX = x - totalWidth / 2 + i * spacing;
        const childY = y + 55;
        return (
          &lt;React.Fragment key={`branch-${depth}-${i}`}&gt;
            &lt;line 
              x1={x} y1={y + 10} x2={childX} y2={childY - 10} 
              className=&quot;stroke-slate-200 stroke-[1.5]&quot; 
            /&gt;
            &lt;g transform={`translate(${childX}, ${childY})`}&gt;
              &lt;circle r=&quot;12&quot; className={`fill-white stroke-2 ${colorClass}`} /&gt;
              &lt;text 
                textAnchor=&quot;middle&quot; 
                dy=&quot;5&quot; 
                className=&quot;text-sm pointer-events-none select-none font-bold&quot;
              &gt;
                {child.name}
              &lt;/text&gt;
              &lt;TreeBranch 
                node={child} 
                x={0} 
                y={0} 
                spacing={spacing * 0.45} 
                depth={depth + 1} 
                colorClass={colorClass}
              /&gt;
            &lt;/g&gt;
          &lt;/React.Fragment&gt;
        );
      })}
    &lt;/g&gt;
  );
};

